/* Original explanations. New lesson IDs preserve older saved attempts. */
const P=(title,paragraphs,example='',diagram='',terms=[])=>({title,paragraphs,example,diagram,terms});
const terminalPages=[
 P('先分清：窗口、Shell、命令',['终端是显示文字和接收键盘输入的窗口。Shell 是解释命令的程序；Bash 是 Linux 上常见的一种 Shell。它们不是同一个东西。','你在窗口输入 pwd，Shell 找到并执行这个命令，窗口显示输出。本站练习区只运行教学模拟，不是本机终端或公司服务器。'],'终端窗口 → 接收输入\nShell → 解释命令\npwd → 显示当前位置','',['终端','Shell','命令']),
 P('提示符：把一行拆成五部分',['student 是用户名：当前用哪个账号操作。@ 是分隔符。lab 是主机名：这台教学机器的名字。','冒号后的 ~ 表示当前用户的家目录。最后的 $ 通常表示普通用户的提示符；这些标记可自定义，所以不能只凭符号判断权限。','只有提示符后面的 pwd 是你输入的命令。执行后出现的 /home/student 是结果。下一行再次出现提示符，表示等待新的输入。'],'student@lab:~$ pwd\n/home/student\nstudent@lab:~$ ▌','',['用户','主机名','家目录']),
 P('普通用户与 root：名字与权限',['student 是一个普通用户的示例名字，不是每台机器都有这个账号。普通用户通常可以管理自己的文件，但不能任意改系统配置或其他人的文件。','root 是 Linux 的超级用户账号，通常 UID 为 0，拥有广泛的系统管理权限。在不同机器、容器和安全策略中，实际可做的动作仍有边界。','# 常被用作 root 提示符；它只是显示约定，提示符可修改。whoami 看有效用户名，id 看 UID 与组，才能取得更可靠的身份信息。'],'student@lab:~$ whoami\nstudent\nroot@lab:~# whoami\nroot','',['root','用户','UID']),
 P('sudo 与用户组：为什么不能随便切换？',['sudo 按系统授权，以另一个身份执行特定命令，常用于管理员操作。不是每个用户都可以 sudo；它也不等于把所有终端永久变成 root。','用户组把多个账号放进同一个权限集合。文件会有属主和属组；系统根据身份与权限判断能否读、写或执行。账号通常有一个主组，还可以加入附加组。','提示符不会列出全部用户组。id 的 uid、gid、groups 分别描述用户编号、主组编号和所属组。组名叫 sudo 也不能单独证明当前命令被授权。'],'uid=1000(student) gid=1000(student) groups=1000(student),27(sudo)\n这是示例输出，不是本机授权信息。','',['sudo','用户组','属主','属组']),
 P('/home/student：这个位置是什么？',['/ 是 Linux 目录树的起点，叫根目录；home 是根目录下的一个目录，student 是 home 下的目录。因此 /home/student 是从根目录到目标位置的完整路径。','它在本课中是 student 的家目录，常用来放个人文件。root 的家目录通常是 /root；“根目录 /”和“root 用户”不是同一概念。','家目录不是命令执行时永远不变的位置。cd 改变当前目录；pwd 再显示当前目录。~ 通常代表当前登录用户的家目录。'],'/                     根目录\n└── home/\n    └── student/      本课普通用户的家目录','',['根目录','家目录','路径']),
 P('先试三件事，不急着管理系统',['现在只需要认识身份、当前位置和输入输出。下一课才深入用户权限，之后认识目录结构。','练习时不要复制 $ 或 #，也不要把返回结果当成下一条命令。看见“成功但无输出”，需要用另一条观察命令验证状态。'],'whoami    看当前有效用户名\npwd       看当前位置\nid        看用户编号与所属组','',['命令','用户组'])
];
const deepBasics=[
 ['users','普通用户、root 与 sudo','用户',['账号是系统判断身份的入口，不是某个人的永久身份证。每个账号有用户名和 UID。root 的 UID 通常为 0，是超级用户；普通账号通常权限较小。','以普通账号学习，先观察再操作。真实环境按授权使用 sudo，不因为教程写了 # 就照抄管理员命令。'],'whoami → student\nid → uid=1000(student) …','root 和根目录 / 是同一个概念吗？','不是，一个是账号，一个是目录树起点',['是，名字相似就一样','是，进入 / 就变成管理员'],'用户身份与文件位置属于两个不同问题。',[
 P('账号用来做什么？',['同一台机器可能有多个用户。系统用身份判断操作是否允许。服务也可以使用专门的系统账号运行，不必由真人登录。'],'whoami → 当前有效用户名\nid → 用户与组编号','',['用户','UID']),
 P('root 强在哪里？',['root 通常是 UID 0 的超级用户。它能管理很多系统对象，因此误操作影响也更大。','普通用户先做只读检查；涉及修改时确认对象、授权、备份和回退。不要把“权限不够”直接理解成必须改成 root。'],'普通用户：管理自己的文件\nroot：广泛系统管理权限，但仍受环境和策略约束','',['root','权限']),
 P('sudo 不是万能解锁',['sudo 执行哪条命令、用哪个身份，由系统规则授权。教程里的 sudo 是操作方式，不是用户已经获准的证据。','本网站不模拟真实提权，也不要求你修改电脑权限。'],'实际工作先确认：我是谁 → 是否获准 → 操作对象 → 如何验证','',['sudo'])
 ]],
 ['groups','用户组与文件权限','用户组',['用户组是共享权限的集合。一个账号通常有主组，也可以属于附加组。文件有属主和属组，权限一般分成属主、属组、其他人三组。','读、写、执行分别常写成 r、w、x。文件的 x 表示允许执行；目录的 x 表示允许穿过这个目录访问其中对象。'],'-rw-r----- student ops app.log','同组就代表能修改组内所有文件吗？','不，还要看文件属组、权限和其他策略',['是，组名相同就完全开放','是，用户组等于 root'],'组成员身份只是判断因素之一，文件权限仍然决定允许范围。',[
 P('为什么需要组？',['让多个运维账号共享某些文件的访问权限，而不是把所有账号都变成 root。','文件属组是这个文件关联的组；用户所属组是账号参与的权限集合。两者要对应，才能使用组权限。'],'账号 student 属于 ops\n文件 app.log 属组 ops\n仍需看该文件的组权限。','',['用户组','属组']),
 P('读懂一行列表',['示例中的第一个 - 表示普通文件；d 常表示目录；l 常表示符号链接。后面九个字符分成三组权限。','rw- 是属主可读写；r-- 是属组可读；--- 是其他人没有这些基本权限。student 和 ops 分别是属主与属组。'],'-rw-r----- student ops app.log\n- | rw- | r-- | ---\n类型  属主  属组  其他人','',['属主','属组','权限']),
 P('目录权限为什么不同？',['文件 r 是读内容，w 是改内容，x 是执行。目录 r 是列出名字，w 关系到创建删除目录项，x 是穿过目录访问其内对象。','能读一个文件还需要能穿过路径中的目录；删除权限通常与父目录有关。ACL、挂载只读等策略也会影响结果。'],'权限不足 → 查身份、文件与上级目录权限 → 按授权处理','',['目录','权限'])
 ]],
 ['tree','Linux 常规目录结构','根目录',['Linux 从 / 开始构成一棵目录树，不是每块磁盘都从 C:、D: 开始。不同文件系统可以挂载到树里的目录位置。','/home 通常放普通用户家目录，/etc 常放配置，/var/log 常放日志，/tmp 放临时内容，/opt 常用于可选应用。具体程序路径以安装和配置为准。'],'/home/student/notes.txt\n/etc/nginx/nginx.conf\n/var/log/nginx/error.log','想找服务日志，能保证都在 /var/log 吗？','不能，需查服务配置、系统日志或容器输出',['能，Linux 规定只能放这里','能，文件名带 log 就一定在这里'],'常见目录是导航线索，不是所有软件必须遵循的唯一位置。',[
 P('先看树，不背路径',['/ 是整棵树的起点。目录里可以放文件和子目录；路径逐层描述如何走到对象。','文件名可以不带扩展名。名字以 . 开头通常隐藏在普通 ls 输出中，ls -a 才包含这些名字。'],'','directory',['根目录','目录','路径']),
 P('配置、应用、日志分别在哪里？',['/etc 常放系统和服务配置；/opt 常放额外安装的应用；/var 保存常变化的数据，/var/log 是常见日志位置。','容器可能写标准输出，由容器平台记录；systemd 服务可能写 journal。先查实际配置，不能只猜目录。'],'Nginx 配置示例：/etc/nginx/\n应用日志示例：/opt/order/logs/app.log\n系统日志：通过 journalctl 查询','',['日志','配置']),
 P('临时目录与系统目录',['/tmp 常放临时文件，可能被清理，重要资料不要只保存在那里。/usr 常包含系统安装的程序和库，并非普通用户个人目录。','/dev 提供设备接口，/proc 和 /sys 提供内核和运行状态相关接口。它们里面的内容不应全部按普通文档文件理解或随意修改。'],'/tmp → 临时内容\n/usr → 系统软件\n/dev、/proc、/sys → 设备或系统接口','',['文件系统','挂载'])
 ]],
 ['path-types','绝对路径、相对路径与家目录','路径',['目录是对象；路径是位置的写法。绝对路径从 / 开始，相对路径从当前目录开始。~ 通常代表当前用户家目录，. 代表当前目录，.. 代表上一级。','这些不是不同物种的目录。同一个目录可以用绝对或相对路径指向；当前目录改变后，相对路径指向也会改变。'],'当前目录 /home/student\nnotes.txt 与 /home/student/notes.txt 指同一文件','相对路径 ../logs 是否固定指向 /var/log？','不是，要结合当前目录解析',['是，logs 永远在 /var/log','是，.. 就是根目录'],'.. 是上一级，结果依赖当前位置。',[
 P('三种位置，先分开',['根目录 / 是树的起点；家目录是账号的个人起点；当前目录是这条命令执行时的位置。三者可能不同。'],'student 家目录：/home/student\n执行 cd /etc 后：当前目录 /etc\n根目录仍是 /','',['家目录','根目录','当前目录']),
 P('同一对象可以有两种写法',['在 /home/student 时，notes.txt 和 /home/student/notes.txt 指向同一个文件。','到 /etc 以后，notes.txt 指向 /etc/notes.txt；绝对路径 /home/student/notes.txt 的指向保持相同。'],'绝对路径：/home/student/notes.txt\n相对路径：notes.txt\n上一级：..','',['路径']),
 P('名字与文件类型不是一回事',['目录、普通文件和符号链接是对象类型；绝对、相对是路径写法；隐藏是名字以 . 开头的习惯。','不要把它们混成一种分类。下一课用文件列表区分普通文件、目录和链接。'],'目录可以通过绝对路径或相对路径访问。','',['目录'])
 ]],
 ['file-types','普通文件、目录与符号链接','符号链接',['普通文件保存内容，目录记录名字与对象的关联，符号链接保存指向另一个路径的引用。链接目标不存在时，链接本身可能还在，但访问失败。','隐藏文件通常只是名字以 . 开头，不是新的底层文件类型。挂载点是文件系统接到目录树的位置，也不是“多一种路径语法”。'],'-rw-r--r-- … notes.txt\ndrwxr-xr-x … practice/\nlrwxrwxrwx … current -> releases/v2','名字以 . 开头就说明是目录吗？','不是，隐藏名字可以属于文件或目录',['是，点号就是目录类型','是，隐藏名字一定无法读取'],'名称习惯、文件类型和权限需要分别判断。',[
 P('先认列表首字符',['ls -l 的首字符常见 -、d、l。分别提示普通文件、目录、符号链接。','不通过扩展名确定全部类型：没有 .txt 的文件也可能是文本，有 .log 的名字也可能是目录。'],'- → 普通文件\nd → 目录\nl → 符号链接','',['符号链接','目录']),
 P('链接为什么会找不到？',['符号链接指向一个路径。目标被移动或删除，链接可能变成断链。','发布应用时 current 指向版本目录是一种常见设计；修改链接会改变访问到的版本，必须按实际流程操作。'],'current → releases/v2\n如果 releases/v2 不存在，访问 current 可能失败。','',['符号链接']),
 P('挂载点与隐藏目录',['挂载让另一个文件系统出现在某个目录，例如 /data。目录名字本身不告诉你是否已挂载，要看实际挂载信息。','隐藏目录以 . 开头，常用于配置。隐藏不等于保密，文件能否被访问取决于权限和其他策略。'],'/data → 可能是挂载点\n.config/ → 名字隐藏的目录','',['挂载','权限'])
 ]]
];
const additions=deepBasics.map(([id,title,term,body,example,q,right,wrong,reason,pages])=>({id:'start-'+id,section:'零基础 · 身份与位置',title,summary:body[0],body,examples:[{text:example,meaning:reason}],related:reason,diagram:'',source:['Linux 文档与原创讲解','https://www.gnu.org/software/coreutils/manual/coreutils.html'],tasks:[choiceTask(q,right,wrong,reason)],quiz:choiceTask(q,right,wrong,reason,1),teachingPages:pages,beginner:true,terms:[term],reminder:'先区分身份、对象与位置，再判断。名字相似不代表概念相同。',transfer:example+'\n'+reason}));
const oldBeginners=hubCurriculum.beginner.slice();
hubCurriculum.beginner=[...oldBeginners.slice(0,2),...additions,...oldBeginners.slice(2)];
hubCurriculum.beginner.find(c=>c.id==='start-terminal').teachingPages=terminalPages;
courses[0].teachingPages=terminalPages;
courses[1].teachingPages=additions.find(c=>c.id==='start-path-types').teachingPages;
const userCourse=courses.find(c=>c.title==='用户与权限');if(userCourse)userCourse.teachingPages=[...additions[0].teachingPages,...additions[1].teachingPages];
Object.assign(beginnerTerms,{用户:'系统账号身份。系统用用户名和 UID 区分账号，并据此参与权限判断。',root:'Linux 超级用户账号，UID 通常为 0。root 用户与根目录 / 是不同概念；不要因教程符号就切换身份。',UID:'用户编号，系统以编号识别账号；root 的 UID 通常为 0。普通账号编号由实际系统分配。',sudo:'按系统规则，以其他身份执行获准的命令。不是每个账号都可以使用，也不是永久成为 root。',用户组:'用于组织账号并共享权限的集合。账号可以有主组与附加组；同组不等于拥有任意权限。',属主:'文件对象关联的拥有者账号。基本权限一般分别为属主、属组和其他人设置。',属组:'文件对象关联的用户组。组成员要结合组权限与其他策略判断是否可访问。',权限:'系统允许谁对对象读、写或执行。文件和目录的 r/w/x 含义不同，还可能受 ACL、只读挂载等影响。',家目录:'账号的个人目录，普通用户常在 /home/用户名，root 常为 /root。~ 通常展开为当前用户家目录。',根目录:'Linux 目录树的起点 /，与名为 root 的超级用户账号不同。',当前目录:'当前进程解析相对路径时使用的位置。pwd 查看它，cd 改变它，不必等于家目录。',主机名:'系统给一台机器配置的名称。提示符里的 lab 是教学主机名，不是当前用户。',文件系统:'组织文件对象、目录和存储的机制。不同文件系统可通过挂载出现在同一目录树中。',挂载:'把一个文件系统接到目录树中的某个位置。位置称挂载点，是否已挂载要查实际状态。',符号链接:'保存另一个路径引用的文件对象。目标改变或不存在时，访问链接可能失败。',配置:'程序运行的设置，例如端口、数据源或日志路径。配置语法有效不代表业务设置一定正确。'});
hubSubjects.beginner.description='逐页认识终端、账号、权限、目录与网络：每次只学一个小主题，再用例子验证理解。';
